package local.royale.replay.android;
import android.app.Instrumentation;
import android.os.Bundle;
import org.json.JSONObject;

/** Device platform tests, no WebView, network, root or game invocation. */
public final class ConsoleTests extends Instrumentation {
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle report=new Bundle();int count=0;try{
        if(BrowserPolicy.allowed("http://royaleapi.com/")||BrowserPolicy.allowed("https://royaleapi.com.evil.test/")||BrowserPolicy.allowed("file:///data/x")||BrowserPolicy.allowed("https://royaleapi.com@evil.test/"))throw new AssertionError("unsafe URL accepted");count++;
        if(!BrowserPolicy.replayTag("https://royaleapi.com/replay?tag=09C9CLU28L9V&x=1").equals("09C9CLU28L9V")||!BrowserPolicy.replayTag("https://royaleapi.com/replay?tag=ABCDEF&tag=ZZZZZZ").isEmpty())throw new AssertionError("tag identity mismatch");count++;
        JSONObject live=new JSONObject().put("state","playing").put("tick",2400).put("native_terminal_tick",6208).put("game_pid",1).put("updated_at",1000).put("monitor_active",true);
        if(!PlaybackStatus.title(live).equals("正在播放 · 2:00 / 5:10")||!PlaybackStatus.canStop(live,1001))throw new AssertionError("live status incorrect");count++;
        if(PlaybackStatus.canStop(live,1040)||!PlaybackStatus.detail(live,1040).contains("状态已过期"))throw new AssertionError("stale status accepted");count++;
        live.put("state","needs_review");if(PlaybackStatus.canStop(live,1001))throw new AssertionError("failed task offered a dead stop");count++;
        live.put("state","complete").put("monitor_active",false);if(PlaybackStatus.canStop(live,1001)||!PlaybackStatus.detail(live,1001).contains("实时观察已结束"))throw new AssertionError("expired monitor accepted");count++;
        JSONObject proof=new JSONObject("{\"errors\":[],\"detached\":true,\"battle_terminal\":true,\"native_replay_scene_present\":true,\"scene_state\":{\"tick\":6208},\"local_driver\":{\"error\":0,\"terminal_tick\":6208}}");
        if(!PlaybackStatus.terminalVerified(proof)||PlaybackStatus.terminalVerified(new JSONObject()))throw new AssertionError("terminal proof gate incorrect");count++;
        proof.getJSONObject("local_driver").put("error",1);if(PlaybackStatus.terminalVerified(proof))throw new AssertionError("failed driver accepted as terminal proof");count++;
        android.app.Notification notification=PlaybackService.progressNotification(getTargetContext(),"测试进度","不发通知、不启动游戏",true);
        if(notification.contentIntent==null||!notification.contentIntent.getCreatorPackage().equals("local.royale.replay.android"))throw new AssertionError("notification has no console return target");count++;
        JSONObject ended=new JSONObject().put("state","complete").put("monitor_active",false).put("client_reopened",true);
        if(!PlaybackService.returnsToConsole(ended,true)||PlaybackService.returnsToConsole(ended,false))throw new AssertionError("completion return must require terminal proof even after client refresh");count++;
        ended.put("state","released");if(PlaybackService.returnsToConsole(ended,false))throw new AssertionError("unproven exit returned console");count++;
        ended.put("generation_released",true);if(!PlaybackService.returnsToConsole(ended,false))throw new AssertionError("confirmed client exit did not return console");count++;
        ended.put("monitor_active",true);if(PlaybackService.returnsToConsole(ended,false))throw new AssertionError("active monitor returned prematurely");count++;
        JSONObject near=new JSONObject().put("page_match","same_towers").put("final_hp_matched",false).put("page_hp_difference",538).put("state","complete");
        if(!PlaybackHandoff.openingTitle(near).contains("终局近似")||PlaybackHandoff.openingTitle(near).contains("校验通过"))throw new AssertionError("near result labelled exact while opening");count++;
        if(!PlaybackStatus.detail(near,1001).contains("538"))throw new AssertionError("ending mismatch disappeared at completion");count++;
        near.put("page_match","different");if(!PlaybackHandoff.openingTitle(near).contains("与网页不符"))throw new AssertionError("different ending hidden while opening");count++;
        JSONObject done=new JSONObject().put("game_pid",1).put("game_start_time","42").put("source_sha256","bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb");
        JSONObject choice=new JSONObject(done.toString()).put("terminal_choice_confirmed",true);
        if(!PlaybackStatus.terminalChoiceMatches(done,choice))throw new AssertionError("explicit terminal choice ignored");count++;
        choice.put("game_start_time","43");if(PlaybackStatus.terminalChoiceMatches(done,choice))throw new AssertionError("other generation dismissed completion");count++;
        choice.put("game_start_time","42").put("source_sha256","cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc");if(PlaybackStatus.terminalChoiceMatches(done,choice))throw new AssertionError("other replay dismissed completion");count++;
        if(ConsoleActions.autoPreparationAllowed(new JSONObject().put("state","complete")))throw new AssertionError("next preparation hid completion choice");count++;
        if(!ConsoleActions.autoPreparationAllowed(new JSONObject().put("state","complete").put("client_reopened",true).put("generation_released",true).put("monitor_active",false)))throw new AssertionError("verified refreshed completion did not advance queue");count++;
        if(ConsoleActions.autoPreparationAllowed(new JSONObject().put("state","complete").put("client_reopened",true).put("generation_released",true).put("monitor_active",true)))throw new AssertionError("active terminal advanced queue");count++;
        if(ConsoleActions.autoPreparationAllowed(new JSONObject().put("state","idle").put("terminal_choice_confirmed",true)))throw new AssertionError("exit auto-started next preparation");count++;
        if(!ConsoleActions.autoPreparationAllowed(new JSONObject().put("state","idle")))throw new AssertionError("initial queue preparation blocked");count++;
        if(ConsoleActions.autoPreparationAllowed(new JSONObject().put("state","idle").put("generation_released",true)))throw new AssertionError("client exit auto-started another preparation");count++;
        String hash="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
        JSONObject matching=new JSONObject().put("state","simulating").put("seed_search_active",true).put("best_source_execution_verified",true).put("monitor_active",true)
            .put("source_sha256",hash).put("game_pid",1).put("game_start_time","42").put("updated_at",1000);
        if(!ConsoleActions.canAcceptBest(matching,1001))throw new AssertionError("complete best cannot be selected");count++;
        matching.put("state","waiting_preparation_lobby");if(!ConsoleActions.canAcceptBest(matching,1001))throw new AssertionError("paused matching cannot select its complete best");count++;matching.put("state","simulating");
        matching.put("best_source_execution_verified",false);if(ConsoleActions.canAcceptBest(matching,1001))throw new AssertionError("partial run selected");count++;
        matching.put("best_source_execution_verified",true).put("state","playing");if(ConsoleActions.canAcceptBest(matching,1001))throw new AssertionError("playing run interrupted by matching control");count++;
        matching.put("state","simulating");if(ConsoleActions.canAcceptBest(matching,1400))throw new AssertionError("stale best selected");count++;
        JSONObject started=new JSONObject().put("state","playing").put("source_sha256",hash).put("updated_at",1000).put("standalone_playback_ready",true).put("native_roundtrip_verified",true).put("playback_started",true).put("scene_frames",3).put("scene_initial_tick",10).put("tick",20).put("game_pid",1).put("game_start_time","42");
        if(PlaybackHandoff.verified(started,hash,1001))throw new AssertionError("missing source proof accepted");count++;
        started.put("source_execution_verified",true);
        if(!PlaybackHandoff.verified(started,hash,1001))throw new AssertionError("fresh verified play refused");count++;
        for(String phase:new String[]{"queued","loading","waiting_lobby","starting","waiting_foreground","needs_review","complete"}){
            started.put("state",phase);if(PlaybackHandoff.verified(started,hash,1001))throw new AssertionError("premature handoff "+phase);count++;
        }
        started.put("state","playing");
        if(PlaybackHandoff.verified(started,hash,1020)||PlaybackHandoff.verified(started,hash.replace('a','b'),1001))throw new AssertionError("stale/foreign source handoff");count++;
        started.put("tick",10);if(PlaybackHandoff.verified(started,hash,1001))throw new AssertionError("no actual step handoff");count++;
        JSONObject generation=new JSONObject().put("game_pid",1).put("game_start_time","42");
        if(NativePython.generationChanged(generation,generation))throw new AssertionError("same process released");count++;
        if(!NativePython.generationChanged(generation,new JSONObject().put("game_pid",1).put("game_start_time","43")))throw new AssertionError("reused PID not detected");count++;
        JSONObject ready=new JSONObject().put("state","ready_to_open").put("source_sha256",hash).put("updated_at",1000).put("source_execution_verified",true).put("native_roundtrip_verified",true).put("retained_events",154).put("game_pid",1).put("game_start_time","42");
        if(!PlaybackHandoff.readyForForeground(ready,hash,1001)||PlaybackHandoff.verified(ready,hash,1001))throw new AssertionError("ready confused with actual playback");count++;
        ready.put("source_execution_verified",false);if(PlaybackHandoff.readyForForeground(ready,hash,1001))throw new AssertionError("incomplete source opened game");count++;
        JSONObject lobby=new JSONObject().put("state","waiting_lobby");
        if(!PlaybackStatus.title(lobby).contains("等待游戏大厅就绪")||!PlaybackStatus.detail(lobby,1001).contains("尚不是播放成功"))throw new AssertionError("lobby wait pretends to play");count++;
        if(!NativePython.releasedStat(generation,0,"REPLAY_PROCESS_ABSENT"))throw new AssertionError("absent process not released");count++;
        try{NativePython.releasedStat(generation,1,"permission denied");throw new AssertionError("permission denial became exit");}catch(java.io.IOException expected){}count++;
        StringBuilder stat=new StringBuilder("1 (game process) S");for(int i=1;i<19;i++)stat.append(" 0");stat.append(" 42");
        if(NativePython.releasedStat(generation,0,stat.toString()))throw new AssertionError("live same generation released");count++;
        if(!NativePython.releasedStat(generation,0,stat.toString().replace(" 42"," 43")))throw new AssertionError("reused PID not released");count++;
        JSONObject release=new JSONObject().put("game_pid",1).put("game_start_time","42").put("generation_released",true);
        if(!PlaybackStatus.releaseMatches(generation,release))throw new AssertionError("valid release ignored");count++;
        release.put("game_start_time","43");if(PlaybackStatus.releaseMatches(generation,release))throw new AssertionError("foreign generation released");count++;
        if(PlaybackStatus.ownsTask(new JSONObject().put("state","released")))throw new AssertionError("released task still owns UI");count++;
        JSONObject pre=new JSONObject().put("state","failed_before_native").put("native_entry_started",false);
        if(!PlaybackStatus.ownsTask(pre)||!NativePython.preparationCandidate(pre))throw new AssertionError("unverified release accepted");count++;
        pre.put("preparation_released",true);
        if(PlaybackStatus.ownsTask(pre))throw new AssertionError("proven pre-native failure blocks replay");count++;
        if(NativePython.preparationCandidate(new JSONObject().put("state","playing")))throw new AssertionError("live scene offered pre-native release");count++;
        java.io.File savedFiles=new java.io.File(getTargetContext().getFilesDir(),"saved-replay-test-"+java.util.UUID.randomUUID());
        if(!savedFiles.mkdir())throw new java.io.IOException("test directory");
        byte[] sample=MainActivity.read(getTargetContext().getAssets().open("synthetic.html"),ReplaySource.MAX_BYTES);
        SavedReplay.save(savedFiles,sample,MainActivity.checkedSource(sample));
        String selectedHash=MainActivity.sha(sample);
        if(!MainActivity.sha(SavedReplay.load(savedFiles,selectedHash)).equals(selectedHash))throw new AssertionError("saved source changed");count++;
        try{SavedReplay.load(savedFiles,hash);throw new AssertionError("wrong source replayed");}catch(java.io.IOException expected){}count++;
        SavedReplay.hide(savedFiles,selectedHash);
        if(SavedReplay.metadata(savedFiles)!=null||!new java.io.File(savedFiles,"source.html").isFile())throw new AssertionError("removal deleted original or remained visible");count++;
        SavedReplay.save(savedFiles,sample,MainActivity.checkedSource(sample));
        if(SavedReplay.metadata(savedFiles)==null)throw new AssertionError("reimport did not restore saved source");count++;
        JSONObject progressState=new JSONObject().put("state","simulating").put("updated_at",1000);
        JSONObject prediction=new JSONObject().put("phase","原生模拟中，等待本分支结果").put("candidate",12).put("seed",-1701922553).put("choice_count",3).put("phase_started_at",990);
        progressState.put("prediction_progress",prediction);
        String narration=PlaybackStatus.detail(progressState,1001);
        if(!narration.contains("第 12 次")||!narration.contains("-1701922553")||!narration.contains("11 秒"))throw new AssertionError("live prediction phase missing");count++;
        if(!narration.contains("尚无溢出圣水与网页一致的完整组合")||narration.contains("当前最优"))throw new AssertionError("placeholder labelled qualified");count++;
        JSONObject lastPrediction=new JSONObject().put("tick",2457).put("accepted",18).put("event_count",85).put("reason","技能分歧，继续展开").put("next_actors",new org.json.JSONArray().put("BossBandit").put("GoldenKnight"));
        prediction.put("last",lastPrediction);narration=PlaybackStatus.detail(progressState,1001);
        if(!narration.contains("2:02")||!narration.contains("18/85")||!narration.contains("首领大盗 / 黄金圣骑"))throw new AssertionError("actual branch stopping point missing");count++;
        lastPrediction.put("skills",new org.json.JSONArray().put(new JSONObject().put("tick",2457).put("owner",0).put("actor","GoldenKnight").put("cost",1)));
        lastPrediction.put("elixir",new org.json.JSONArray().put(new JSONObject().put("owner",1).put("simulated",11.6627).put("page",11.66)));
        narration=PlaybackStatus.detail(progressState,1001);
        if(!narration.contains("黄金圣骑（1 圣水）")||!narration.contains("11.6627 / 网页 11.66"))throw new AssertionError("skill/elixir details missing");count++;
        prediction.put("best",new JSONObject().put("hp_difference",491).put("time_difference_seconds",15.8).put("match_cost",30091));
        narration=PlaybackStatus.detail(progressState,1001);
        if(!narration.contains("六塔血差 491")||!narration.contains("+15.80 秒")||!narration.contains("含终局时间和溢出圣水"))throw new AssertionError("qualified metrics hidden");count++;
        prediction.getJSONObject("best").put("time_penalty",29700).put("elixir_penalty",0);
        narration=PlaybackStatus.detail(progressState,1001);
        if(!narration.contains("塔血差 491 + 时间罚分 29700 + 圣水罚分 0"))throw new AssertionError("score components not tied to best candidate");count++;
        prediction.getJSONObject("best").put("time_penalty",JSONObject.NULL);
        if(!PlaybackStatus.detail(progressState,1001).contains("时间罚分 未知"))throw new AssertionError("unknown timing penalty became zero");count++;
        lastPrediction.put("failure_explanation","原生引擎已提前结算，请检查客户端版本及回放日期");
        if(!PlaybackStatus.detail(progressState,1001).contains("请检查客户端版本及回放日期"))throw new AssertionError("terminal version hint hidden");count++;
        if(!DiagnosticExport.VERSION.equals(getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),0).versionName))throw new AssertionError("diagnostic export reports stale app version");count++;
        progressState.put("skill_pool_mode",true).put("skill_pool_size",16).put("skill_pool_screen_limit",2);
        if(!PlaybackStatus.detail(progressState,1001).contains("首轮最多 2/16 组代表候选"))throw new AssertionError("unbounded pool screen shown");count++;
        progressState.put("alns_allocation",new JSONObject().put("tested_combinations",2).put("deferred_pool_candidates",14).put("refinement_used",3).put("refinement_budget_total",24));
        narration=PlaybackStatus.detail(progressState,1001);
        if(!narration.contains("待验证 14 组")||!narration.contains("精修新增 3/24"))throw new AssertionError("deferred pool/budget hidden");count++;
        progressState.put("state","playing").put("message","已播放");
        if(PlaybackStatus.detail(progressState,1001).contains("第 12 次"))throw new AssertionError("old prediction covers live playback");count++;
        report.putString("summary","PASS "+count+" console/handoff/status tests; no network or native playback invoked");finish(-1,report);
    }catch(Throwable error){report.putString("error",error.toString());finish(0,report);}}
}
